            fifo_mem[fifo_head] <= data;
            fifo_head <= fifo_head + 1;
            fifo_count <= fifo_count + 1;
            if (fifo_head == 256) begin
                fifo_head <= 0;
            end
        end
        if (rdreq && !empty) begin
            q <= fifo_mem[fifo_tail];
            fifo_tail <= fifo_tail + 1;
            fifo_count <= fifo_count - 1;
            if (fifo_tail == 256) begin
                fifo_tail <= 0;
            end
        end
    end

endmodule

