module top_module(
  input clk, // Clock signal input 
  input rst_n, // Active low synchronous reset input 
  output reg [63:0] JC_out, // 64-bit output from Johnson counter 
  output reg [2:0] SR_out, // 3-bit output from shift register 
  output reg [7:0] final_out // 8-bit output from functional module 
);reg [3:0] johnson; // 4-bit Johnson counter 
  reg [2:0] shift_reg; // 3-bit shift register 

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      johnson <= 4'b0000;
      shift_reg <= 3'b000;
      JC_out <= 64'b0;
      SR_out <= 3'b0;
      final_out <= 8'b0;
    end else begin
      // Johnson counter logic 
      case (johnson)
        4'b0000: johnson <= 4'b1000;
        4'b1000: johnson <= 4'b1100;
        4'b1100: johnson <= 4'b1110;
        4'b1110: johnson <= 4'b1111;
        4'b1111: johnson <= 4'b0111;
        4'b0111: johnson <= 4'b0011;
        4'b0011: johnson <= 4'b0001;
        4'b0001: johnson <= 4'b0000;
      endcase

      // Shift register logic 
      shift_reg <= {shift_reg[1:0], JC_out[0]};

      // Output logic 
      JC_out <= {JC_out[62:0], johnson[0]};
      SR_out <= shift_reg;
      final_out <= {JC_out[55], SR_out[2], JC_out[23], SR_out[1], JC_out[7], SR_out[0], JC_out[39], SR_out[2]};
    end
  end

endmodule

