module fsm (
	input clk,
	input reset,
	input j,
	input k,
	output reg y);

	parameter R=0, S=1, S1=2, S2=3;
	reg [2:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= R;
		else state <= next;
	end

	always_comb begin
		case (state)
			R: next = j ? S : R;
			S: next = k ? S1 : S2;
			S1: next = k ? R : S;
			S2: next = k ? S : R;
			default: next = 'x;
		endcase
	end

	assign y = (state == S1);

endmodule

