module top_module(
  input rst_in,
  input clk_in,
  input clk_out,
  output reg rst_out
);reg [1:0] rst_sync1;
  reg [1:0] rst_sync2;

  // Define D flip-flops for first stage of synchronizer
  always @(posedge clk_in) begin
    rst_sync1 <= {rst_sync1[0], rst_in};
  end

  always @(posedge clk_in) begin
    rst_sync2 <= {rst_sync2[0], rst_sync1[1]};
  end

  // Define D flip-flops for second stage of synchronizer
  always @(posedge clk_out) begin
    rst_out <= rst_sync2[1];
  end

  // Minimum pulse width detector to hold reset signal for one clock cycle
  always @(posedge clk_out) begin
    if (rst_out) begin
      rst_out <= 1'b0;
    end
  end

endmodule

