module top_module(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data_in,
    input [1:0] rot_ena,
    input [99:0] rot_data_in,
    output reg [103:0] q);reg [3:0] shift_reg;
    reg [99:0] rot_reg;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            shift_reg <= 4'b0;
            rot_reg <= 100'b0;
        end else begin
            if (load) begin
                shift_reg <= data_in;
            end else if (ena) begin
                shift_reg <= {shift_reg[2:0], shift_reg[3]};
            end
            if (rot_ena[0]) begin
                rot_reg <= {rot_reg[98:0], rot_data_in[0]};
            end else if (rot_ena[1]) begin
                rot_reg <= {rot_data_in[99], rot_reg[99:1]};
            end
        end
    end

    assign q = {shift_reg, rot_reg};

endmodule

