module top_module(
        // global
        input  wire                clk_i,
        input  wire                reset_i,
        // write port
        input  wire                wreg_a_wr_i,
        input  wire          [4:0] wreg_a_addr_i,
        input  wire          [31:0] wreg_a_data_i,
        input  wire                wreg_b_wr_i,
        input  wire          [4:0] wreg_b_addr_i,
        input  wire          [31:0] wreg_b_data_i,
        // read port
        input  wire                rreg_a_rd_i,
        input  wire          [4:0] rreg_a_addr_i,
        output reg  [31:0] rreg_a_data_o,
        input  wire                rreg_b_rd_i,
        input  wire          [4:0] rreg_b_addr_i,
        output reg  [31:0] rreg_b_data_o
    );//--------------------------------------------------------------

    reg [31:0] mem[0:31]; // Changed the memory address range to include 0 to 31

    //--------------------------------------------------------------

    //--------------------------------------------------------------
    // write
    //--------------------------------------------------------------
    always @ (posedge clk_i) begin
        if (reset_i) begin
            // Reset individual registers in the memory
            integer i;
            for (i = 0; i < 32; i = i + 1) begin
                mem[i] <= 32'b0;
            end
        end else begin
            // write port a
            if (wreg_a_wr_i) begin
                mem[wreg_a_addr_i] <= wreg_a_data_i;
            end
            // write port b
            if (wreg_b_wr_i) begin
                mem[wreg_b_addr_i] <= wreg_b_data_i;
            end
        end
    end


    //--------------------------------------------------------------
    // read
    //--------------------------------------------------------------
    always @ (*) begin
        // read port a
        if (rreg_a_rd_i && rreg_a_addr_i != 5'b0) begin
            rreg_a_data_o = mem[rreg_a_addr_i];
        end else begin
            rreg_a_data_o = 32'b0;
        end
        // read port b
        if (rreg_b_rd_i && rreg_b_addr_i != 5'b0) begin
            rreg_b_data_o = mem[rreg_b_addr_i];
        end else begin
            rreg_b_data_o = 32'b0;
        end
    end
endmodule

