module top_module(
    // Inputs
     input           clk0_i,
     input           rst0_i,
     input  [  7:0]  addr0_i,
     input           clk1_i,
     input           rst1_i,
     input  [  7:0]  addr1_i,
     input  [ 20:0]  data1_i,
     input           wr1_i,

    // Outputs
     output reg [ 20:0]  data0_o  // Change output to reg
);// Define tag RAM
reg [20:0] tag_ram [255:0];

// Define read and write pointers
reg [7:0] read_ptr;
reg [7:0] write_ptr;

// Define read and write flags
reg read_flag;
reg write_flag;

// Define read and write data
reg [20:0] read_data;
reg [20:0] write_data;

// Initialize pointers and flags
initial begin
    read_ptr = 0;
    write_ptr = 0;
    read_flag = 0;
    write_flag = 0;
end

// Read data from tag RAM
always @(posedge clk1_i) begin
    if (rst1_i) begin
        read_ptr <= 0;
        read_flag <= 0;
    end else begin
        if (addr0_i != read_ptr) begin
            read_ptr <= addr0_i;
            read_flag <= 1;
        end else begin
            read_flag <= 0;
        end
    end
end

// Write data to tag RAM
always @(posedge clk1_i) begin
    if (rst1_i) begin
        write_ptr <= 0;
        write_flag <= 0;
    end else begin
        if (wr1_i) begin
            write_ptr <= addr1_i;
            write_data <= data1_i;
            write_flag <= 1;
        end else begin
            write_flag <= 0;
        end
    end
end

// Read and write data from tag RAM
always @(posedge clk0_i) begin
    if (rst0_i) begin
        data0_o <= 0;
    end else begin
        if (read_flag) begin
            read_data <= tag_ram[read_ptr];
        end
        if (write_flag) begin
            tag_ram[write_ptr] <= write_data;
        end
        data0_o <= read_data; // This becomes valid since data0_o is a reg
    end
end

endmodule

