module top_module(D,
    Q,
    s_aclk,
    AR);output [3:0]D;
  input [3:0]Q;
  input s_aclk;
  input AR;

  wire AR;
  wire [3:0]Q;
  reg [3:0]Q_reg;
  wire s_aclk;

