module fsm (
  input in,
  input [2:0] state,
  output reg [2:0] next_state,
  output reg out);parameter U=0, V=1, W=2, X=3, Y=4;

    always_comb begin
        case (state)
            U: next_state = in ? W : V;
            V: next_state = in ? X : U;
            W: next_state = in ? V : Y;
            X: next_state = in ? U : W;
            Y: next_state = in ? U : X;
        endcase
    end

    assign out = (state==V) || (state==X);

endmodule

