module pedestrian_crossing_light (
	input clk,
	input resetn,
	input button,
	output reg walk);

	parameter WAIT=0, WALK=1;
	reg state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= WAIT;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			WAIT: next_state = button ? WALK : WAIT;
			WALK: next_state = button ? WALK : WAIT;
			default: next_state = WAIT;
		endcase
	end

	always @(state) begin
		case (state)
			WALK: walk = 1;
			default: walk = 0;
		endcase
	end
endmodule

