module up_down_counter
    (
		input clk,
        input rst_n,
        input mode,
        output reg [2:0] count
    );

always @(posedge clk or negedge rst_n) 
    begin
        if (!rst_n)
            count <= 3'b000;
        else if (mode)
            count <= count + 1;
        else
            count <= count - 1;
    end

