code:
module counter(
    input clk,
    input reset_n,
    output reg [3:0] q
);

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            // Asynchronous active low reset
            q <= 4'b0000;
        end else begin
            // Increment the counter
            q <= q + 1;
        end
    end

endmodule

