module top_module(
	output reg[15:0] listOut,
	input [15:0] listIn,
	input [2:0] nShift
);always @(listIn or nShift)
begin
	case(nShift) 
	3'b000: begin 
	listOut[15:0] <= listIn[15:0]; 
	end

	3'b001: begin 
	listOut[15:1] <= listIn[14:0]; 
	listOut[0] <= 0;
	end

	3'b010: begin 
	listOut[14:0] <= listIn[15:1]; 
	listOut[15] <= 0;
	end

	3'b011: begin 
	listOut[15:1] <= listIn[14:0]; 
	listOut[0] <= listIn[15];
	end

	3'b100: begin 
	listOut[14:0] <= listIn[15:1]; 
	listOut[15] <= listIn[0];
	end

	default: listOut[15:0] <= listIn[15:0];

	endcase
end
