module top_module (
        input clk,
        input reset,
        input start,
        input done,
        output reg out);parameter IDLE=0, LOAD=1, EXECUTE=2, STORE=3;
	reg[1:0] state, next;

	always @(posedge clk)
		if (reset) state <= IDLE;
		else state <= next;


	always_comb begin
		case (state)
			IDLE: next = start ? LOAD : IDLE;
			LOAD: next = done ? EXECUTE : LOAD;
			EXECUTE: next = done ? STORE : EXECUTE;
			STORE: next = done ? IDLE : STORE;
			default: next = 'x;
		endcase
	end

	assign out = (state == EXECUTE) || (state == STORE);

endmodule

