module fsm_module (
        input clk,
        input reset,
        input a,
        output reg z);parameter X=0, Y=1, Z=2, W=3;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= X;
		else 
			state <= next;

	always_comb begin
		case(state)
			X: next = a ? Z : Y;
			Y: next = a ? X : W;
			Z: next = a ? W : X;
			W: next = a ? Z : Y;
			default: next = 'x;
		endcase
	end

	assign z = (state == X || state == Z);

endmodule

